from mk import *
from lib import fbd
STRICT["on"] = True
import math
G = 6.67e-11; Ms = 1.99e30; r = 1.5e11; Ty = 365 * 86400; m = 800
v = 2 * math.pi * r / Ty
Te = (1.01e13 / r) ** 1.5
E0 = G * Ms * m / (2 * r)

def fig():
    g = Fig(560, 260, "השמש במרכז. מסלול כדור הארץ, והחללית על אותו מסלול. רחוק יותר: מסלול גדול של אריס")
    cx, cy = 200, 130
    g.circle(cx, cy, 18, fill="var(--d-accent, var(--d-body))"); g.heb(cx, cy + 40, "שמש")
    g.circle(cx, cy, 70, fill="none", stroke="var(--d-line)", width=1.3, dash="5 4")
    g.circle(cx + 70, cy, 7); g.heb(cx + 82, cy + 4, "כדור הארץ", anchor="start")
    g.ball(cx - 50, cy - 49, r=5); g.heb(cx - 74, cy - 62, "חללית")
    g.path(f"M {cx + 300} {cy - 120} A 300 300 0 0 1 {cx + 300} {cy + 120}", width=1.2, dash="3 5")
    g.circle(cx + 300 - 1, cy, 6, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(cx + 270, cy - 16, "אריס")
    return g

E(id="bagrut-2010-q5", year=2010, label="2010 שאלה 5", topic="gravitation", sub="grav-energy", diff=3, fig=fig,
  stem=r"משגרים חללית מכדור הארץ כדי לחקור את מערכת השמש. בשלב הראשון החללית נעה סביב השמש במסלול מעגלי, ברדיוס של המסלול של כדור הארץ סביב השמש. בכל החישובים מזניחים את ההשפעה של כדור הארץ ושל שאר כוכבי הלכת על החללית. נתונים: מסת השמש $1.99 \times 10^{30}\,\text{kg}$, רדיוס המסלול של כדור הארץ $1.5 \times 10^{11}\,\text{m}$, ובשנה $365$ יממות.",
  parts=[
    P("א1", r"המהירות של החללית שווה למהירות של כדור הארץ סביב השמש. הסבירו למה.", OPEN, ["principle"], [
        S(r"משוואת כוחות בכיוון המרכז", r"כוח הכבידה של השמש נותן את התאוצה אל המרכז. המסה של הגוף שנע מצטמצמת, ולכן המהירות תלויה רק במסת השמש וברדיוס", r"\frac{GM_S m}{r^2} = m\frac{v^2}{r} \;\Rightarrow\; v = \sqrt{\frac{GM_S}{r}}", eq=r"F = \frac{GMm}{r^2},\qquad a_R = \frac{v^2}{r}"),
    ], r"אותו רדיוס ואותה מסה במרכז, ולכן אותה מהירות"),
    P("א2", r"מה המהירות של החללית?", num(v, "m/s", tol=2), ["algebra", "units"], [
        S(r"היקף חלקי זמן מחזור", r"זמן המחזור כמו של כדור הארץ, שנה. ממירים לשניות", r"v = \frac{2\pi r}{T} = \frac{2\pi \cdot 1.5 \times 10^{11}}{365 \cdot 86400} \approx 2.99 \times 10^4\,\text{m/s}", eq=r"v = \frac{2\pi r}{T}"),
        C(r"בדיקה בדרך אחרת", r"מהביטוי מהסעיף הקודם", r"v = \sqrt{\frac{6.67 \times 10^{-11} \cdot 1.99 \times 10^{30}}{1.5 \times 10^{11}}} \approx 2.97 \times 10^4\,\text{m/s}"),
    ], r"$v \approx 2.98 \times 10^4\,\text{m/s}$", key=r"v=2.98×10^4 m/s"),
    P("ב", r"בשנת 2005 התגלה במערכת השמש גוף דמוי כוכב לכת בשם \"אריס\", במרחק $1.01 \times 10^{10}\,\text{km}$ מהשמש. אם אריס נע סביב השמש במסלול מעגלי, מה זמן המחזור שלו, בשנים?", num(Te, "year", tol=1), ["principle", "algebra", "units"], [
        S(r"קפלר ביחס לכדור הארץ", r"שני הגופים נעים סביב השמש, ולכן היחס שלהם זהה", r"\frac{T_E^2}{r_E^3} = \frac{T^2}{r^3}", eq=r"\frac{r^3}{T^2} = \frac{GM}{4\pi^2}"),
        S(r"מציבים", r"ממירים קילומטרים למטרים. זמן המחזור של כדור הארץ שנה אחת", r"T = 1 \cdot \left(\frac{1.01 \times 10^{13}}{1.5 \times 10^{11}}\right)^{3/2} \approx 552\ \text{y}"),
    ], r"$\approx 552$ שנים", key=r"552.5 year"),
    P("ג", r"בזמן שהחללית נעה במסלול סביב השמש, מפעילים את המנועים שלה. מסת החללית $800\,\text{kg}$. מה האנרגיה המזערית $E_0$ שצריך להוסיף לחללית כדי שתעזוב את מערכת השמש?", num(E0, "J", tol=2), ["principle", "algebra"], [
        S(r"האנרגיה הכוללת במסלול מעגלי", r"האנרגיה הקינטית היא חצי מגודל האנרגיה הפוטנציאלית", r"E = \frac{GM_S m}{2r} - \frac{GM_S m}{r} = -\frac{GM_S m}{2r}", eq=r"U = -\frac{GMm}{r}"),
        S(r"כדי לעזוב: אנרגיה כוללת אפס", r"באנרגיה המזערית החללית מגיעה לאינסוף בלי מהירות", r"E_0 = 0 - E = \frac{GM_S m}{2r} = \frac{6.67 \times 10^{-11} \cdot 1.99 \times 10^{30} \cdot 800}{2 \cdot 1.5 \times 10^{11}} \approx 3.54 \times 10^{11}\,\text{J}"),
    ], r"$E_0 \approx 3.5 \times 10^{11}\,\text{J}$", key=r"E0=+3.56×10^11 J"),
    P("ד", r"רוצים לשגר את החללית מהמסלול שלה אל אריס. בלי חישוב, האם האנרגיה המזערית שצריך להוסיף גדולה מ-$E_0$, קטנה ממנה או שווה לה? הסבירו.", choice([r"גדולה מ-$E_0$", r"קטנה מ-$E_0$", r"שווה ל-$E_0$"], 1), ["principle"], [
        S(r"אריס עוד בשדה של השמש", r"האנרגיה הפוטנציאלית שם עדיין שלילית, כלומר קטנה מאשר באינסוף", r"U(r) < 0"),
        S(r"משווים", r"כדי להגיע לאריס צריך פחות אנרגיה מאשר כדי להגיע לאינסוף", r"\Delta E < E_0"),
    ], r"קטנה מ-$E_0$", key=r"smaller than it"),
  ],
  concepts=["מהירות במסלול", "החוק השלישי של קפלר", "אנרגיה כוללת במסלול", "אנרגיית מילוט"],
  summary=r"חללית במסלול של כדור הארץ סביב השמש: המהירות, זמן המחזור של אריס, והאנרגיה שצריך כדי לעזוב את מערכת השמש.",
  review="הבדל קטן מדף התשובות, בסעיף ג (האנרגיה לעזוב את מערכת השמש).\nבדף התשובות: 3.56 כפול 10 בחזקת 11 ג'אול.\nאצלי: 3.54 כפול 10 בחזקת 11 ג'אול.\nלמה: ההבדל נובע מעיגול מסת השמש. האתר מקבל את שתי התשובות.\nמה לבדוק: רק לאשר.")
